using EHub.Domain.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EHub.Infrastructure.Persistence.Configurations;
public sealed class ProductFeedbackConfiguration : IEntityTypeConfiguration<ProductFeedback>
{ public void Configure(EntityTypeBuilder<ProductFeedback> b) { b.ToTable("product_feedbacks"); b.HasKey(x=>x.Id); b.Property(x=>x.Category).HasConversion<string>().HasMaxLength(32).IsRequired(); b.Property(x=>x.Priority).HasConversion<string>().HasMaxLength(16).IsRequired(); b.Property(x=>x.Title).HasMaxLength(150).IsRequired(); b.Property(x=>x.Description).HasMaxLength(3000).IsRequired(); b.Property(x=>x.ContextUrl).HasMaxLength(1000); b.Property(x=>x.Version).IsRowVersion().HasColumnName("xmin"); b.HasIndex(x=>new{x.IsArchived,x.CreatedAt}); b.HasIndex(x=>x.ReporterUserId); b.HasQueryFilter(x=>!x.IsDeleted); b.HasOne(x=>x.ReporterUser).WithMany().HasForeignKey(x=>x.ReporterUserId).OnDelete(DeleteBehavior.Restrict); } }
